INSERT INTO public.testimonials (id, client_name, business_name, review, rating, avatar_url, video_url, service_type, is_featured, is_published, sort_order, created_at) VALUES ('dff5e457-04a5-4e5f-bfb8-2d755a89dbfc', 'Rahul Mehta', 'TechNova Solutions', 'Shivam Creates completely transformed our brand identity. The new website is not just beautiful, it’s lightning fast. We saw a 40% increase in lead conversions within the first month. Highly recommended for any ambitious startup!', 5, NULL, NULL, 'Web Development & Branding', true, true, 1, '2026-07-12T19:05:47.420796+00:00');
