INSERT INTO public.testimonials (id, client_name, business_name, review, rating, avatar_url, video_url, service_type, is_featured, is_published, sort_order, created_at) VALUES ('1e734342-945a-4f2a-be70-fca4edb6608f', 'Alex K.', 'Elevate Fitness', 'Working with Shivam Creates was the best investment for my business. The mobile app he developed for my fitness coaching program is flawless. Fast communication, premium quality, and delivered exactly on time.', 5, NULL, NULL, 'App Development', true, true, 3, '2026-07-12T19:05:47.420796+00:00');
